/**
 * Canonical Road Geometry Domain Model & Registry
 *
 * Provides a single, authoritative source of truth for road segment geometry
 * across both 2D Leaflet map views and 3D Globe / MapLibre projections.
 *
 * Conforms to:
 * - RFC 7946 GeoJSON Standard: positions are strictly [longitude, latitude]
 * - WGS 84 / EPSG:4326 Coordinate Reference System
 * - Validated OpenStreetMap (OSM) highway centerline traces
 * - Uncoupled from report marker positions (reports are incident points, road centerlines are linear assets)
 */

import type { RoadSegment } from '../../types';

export type GeometrySource = 'OSM_CENTERLINE' | 'VERIFIED_GIS' | 'ILLUSTRATIVE';
export type GeometryStatus = 'DIGITISED' | 'ILLUSTRATIVE';
export type ValidationStatus = 'VALID' | 'UNVERIFIED';

export interface GeoJsonLineString {
  readonly type: 'LineString';
  /** Standard GeoJSON order: [longitude, latitude] */
  readonly coordinates: readonly [number, number][];
}

export interface CanonicalRoadGeometry {
  readonly id: string;
  readonly name: string;
  readonly crs: 'EPSG:4326';
  readonly geometrySource: GeometrySource;
  readonly geometryStatus: GeometryStatus;
  readonly validationStatus: ValidationStatus;
  readonly lengthKm: number;
  readonly geometry: GeoJsonLineString;
}

export type ReportMatchStatus =
  | 'MATCHED_BY_ID'
  | 'MATCHED_BY_PROXIMITY'
  | 'NO_ROAD_FOUND'
  | 'INVALID_COORDINATES';

export interface ReportMatchResult {
  readonly segment: RoadSegment | null;
  readonly status: ReportMatchStatus;
  readonly distanceMeters: number | null;
  /** Snapped point on the road centerline [lat, lng], keeping original report coordinates untouched */
  readonly snappedCoordinates: [number, number] | null;
  readonly isCorridorMatched: boolean;
}

const EARTH_RADIUS_METERS = 6371000;
const DEG_TO_RAD = Math.PI / 180;

/**
 * Validates that an input is a valid [latitude, longitude] pair with finite numbers within WGS84 range.
 */
export function isValidLatLng(coords: unknown): coords is [number, number] {
  if (!Array.isArray(coords) || coords.length !== 2) return false;
  const [lat, lng] = coords;
  return (
    typeof lat === 'number' &&
    typeof lng === 'number' &&
    Number.isFinite(lat) &&
    Number.isFinite(lng) &&
    lat >= -90 &&
    lat <= 90 &&
    lng >= -180 &&
    lng <= 180
  );
}

/**
 * Validates that an input is a valid GeoJSON [longitude, latitude] pair.
 */
export function isValidLngLat(coords: unknown): coords is [number, number] {
  if (!Array.isArray(coords) || coords.length !== 2) return false;
  const [lng, lat] = coords;
  return (
    typeof lng === 'number' &&
    typeof lat === 'number' &&
    Number.isFinite(lng) &&
    Number.isFinite(lat) &&
    lng >= -180 &&
    lng <= 180 &&
    lat >= -90 &&
    lat <= 90
  );
}

/**
 * Validates that a LineString contains at least 2 valid coordinates and no NaN/Infinity.
 */
export function isValidLineString(coords: unknown): coords is [number, number][] {
  if (!Array.isArray(coords) || coords.length < 2) return false;
  return coords.every(isValidLngLat);
}

/**
 * Converts standard GeoJSON [longitude, latitude] coordinates to Leaflet [latitude, longitude].
 */
export function toLeafletPolyline(geoJsonCoords: readonly [number, number][]): [number, number][] {
  if (!Array.isArray(geoJsonCoords)) return [];
  return geoJsonCoords
    .filter(isValidLngLat)
    .map(([lng, lat]) => [lat, lng]);
}

/**
 * Converts Leaflet [latitude, longitude] coordinates to standard GeoJSON [longitude, latitude].
 */
export function toGeoJsonCoordinates(leafletCoords: readonly [number, number][]): [number, number][] {
  if (!Array.isArray(leafletCoords)) return [];
  return leafletCoords
    .filter(isValidLatLng)
    .map(([lat, lng]) => [lng, lat]);
}

/**
 * Haversine great-circle distance between two [lat, lng] points in meters.
 */
export function haversineDistanceMeters(
  a: readonly [number, number],
  b: readonly [number, number]
): number {
  const dLat = (b[0] - a[0]) * DEG_TO_RAD;
  const dLng = (b[1] - a[1]) * DEG_TO_RAD;
  const lat1 = a[0] * DEG_TO_RAD;
  const lat2 = b[0] * DEG_TO_RAD;

  const sinHalfLat = Math.sin(dLat / 2);
  const sinHalfLng = Math.sin(dLng / 2);
  const h = sinHalfLat * sinHalfLat + Math.cos(lat1) * Math.cos(lat2) * sinHalfLng * sinHalfLng;
  return 2 * EARTH_RADIUS_METERS * Math.asin(Math.min(1, Math.sqrt(h)));
}

/**
 * Projects point Q onto segment AB on a local tangent plane.
 * Coordinates are [lat, lng].
 */
export function projectPointToLineSegment(
  q: readonly [number, number],
  a: readonly [number, number],
  b: readonly [number, number]
): { distanceMeters: number; snapped: [number, number] } {
  const latMid = ((a[0] + b[0]) / 2) * DEG_TO_RAD;
  const cosLat = Math.cos(latMid);

  const dxB = (b[1] - a[1]) * DEG_TO_RAD * EARTH_RADIUS_METERS * cosLat;
  const dyB = (b[0] - a[0]) * DEG_TO_RAD * EARTH_RADIUS_METERS;

  const dxQ = (q[1] - a[1]) * DEG_TO_RAD * EARTH_RADIUS_METERS * cosLat;
  const dyQ = (q[0] - a[0]) * DEG_TO_RAD * EARTH_RADIUS_METERS;

  const lenSq = dxB * dxB + dyB * dyB;

  if (lenSq < 1e-8) {
    const d = Math.hypot(dxQ, dyQ);
    return { distanceMeters: d, snapped: [a[0], a[1]] };
  }

  const t = Math.max(0, Math.min(1, (dxQ * dxB + dyQ * dyB) / lenSq));
  const projX = t * dxB;
  const projY = t * dyB;
  const distanceMeters = Math.hypot(dxQ - projX, dyQ - projY);

  const snappedLat = a[0] + (b[0] - a[0]) * t;
  const snappedLng = a[1] + (b[1] - a[1]) * t;

  return {
    distanceMeters,
    snapped: [Number(snappedLat.toFixed(6)), Number(snappedLng.toFixed(6))]
  };
}

/**
 * Evaluates the perpendicular distance from point Q [lat, lng] to a polyline [lat, lng][].
 */
export function distanceToPolyline(
  point: readonly [number, number],
  polyline: readonly [number, number][]
): { distanceMeters: number; snapped: [number, number] } {
  if (polyline.length === 0) {
    return { distanceMeters: Infinity, snapped: [point[0], point[1]] };
  }
  if (polyline.length === 1) {
    return { distanceMeters: haversineDistanceMeters(point, polyline[0]), snapped: [polyline[0][0], polyline[0][1]] };
  }

  let bestDist = Infinity;
  let bestSnapped: [number, number] = [polyline[0][0], polyline[0][1]];

  for (let i = 0; i < polyline.length - 1; i++) {
    const { distanceMeters, snapped } = projectPointToLineSegment(point, polyline[i], polyline[i + 1]);
    if (distanceMeters < bestDist) {
      bestDist = distanceMeters;
      bestSnapped = snapped;
    }
  }

  return { distanceMeters: bestDist, snapped: bestSnapped };
}

