/**
 * Retrieves the canonical geometry for a given road segment ID.
 */
export function getCanonicalRoadGeometry(segmentId: string): CanonicalRoadGeometry | null {
  return CANONICAL_ROAD_GEOMETRIES[segmentId] ?? null;
}

/**
 * Gets Leaflet-compatible [latitude, longitude][] polyline coordinates for a road segment,
 * always reading from the canonical geometry when available.
 */
export function getCanonicalLeafletPolyline(segment: RoadSegment): [number, number][] {
  const canonical = getCanonicalRoadGeometry(segment.id);
  if (canonical && isValidLineString(canonical.geometry.coordinates)) {
    return toLeafletPolyline(canonical.geometry.coordinates);
  }
  if (segment.polyline && segment.polyline.length > 1) {
    return segment.polyline.filter(isValidLatLng);
  }
  return [segment.coordinates];
}

/**
 * Matches an incident report to its legitimate road segment based on:
 * 1. Verified segment ID if provided and confirmed within corridor threshold.
 * 2. Spatial geometric nearest-road evaluation against canonical road centerlines.
 *
 * Maintains the original report coordinates intact. Never forces a false road match.
 */
export function matchReportToRoadSegment(
  reportCoordinates: unknown,
  segments: readonly RoadSegment[],
  reportedSegmentId?: string | null,
  maxSearchRadiusMeters: number = 2500
): ReportMatchResult {
  if (!isValidLatLng(reportCoordinates)) {
    return {
      segment: null,
      status: 'INVALID_COORDINATES',
      distanceMeters: null,
      snappedCoordinates: null,
      isCorridorMatched: false
    };
  }

  // 1. If explicit segment ID is given, verify against its canonical centerline
  if (reportedSegmentId) {
    const declaredSegment = segments.find((s) => s.id === reportedSegmentId);
    if (declaredSegment) {
      const line = getCanonicalLeafletPolyline(declaredSegment);
      const { distanceMeters, snapped } = distanceToPolyline(reportCoordinates, line);
      // If within 2500m of the declared corridor, match is confirmed by ID
      if (distanceMeters <= maxSearchRadiusMeters) {
        return {
          segment: declaredSegment,
          status: 'MATCHED_BY_ID',
          distanceMeters: Math.round(distanceMeters),
          snappedCoordinates: snapped,
          isCorridorMatched: true
        };
      }
    }
  }

  // 2. Spatial nearest-road search across all available segments
  let bestSegment: RoadSegment | null = null;
  let bestDist = Infinity;
  let bestSnapped: [number, number] | null = null;

  for (const seg of segments) {
    const line = getCanonicalLeafletPolyline(seg);
    const { distanceMeters, snapped } = distanceToPolyline(reportCoordinates, line);
    if (distanceMeters < bestDist) {
      bestDist = distanceMeters;
      bestSegment = seg;
      bestSnapped = snapped;
    }
  }

  if (bestSegment && bestDist <= maxSearchRadiusMeters) {
    return {
      segment: bestSegment,
      status: 'MATCHED_BY_PROXIMITY',
      distanceMeters: Math.round(bestDist),
      snappedCoordinates: bestSnapped,
      isCorridorMatched: true
    };
  }

  return {
    segment: null,
    status: 'NO_ROAD_FOUND',
    distanceMeters: bestDist === Infinity ? null : Math.round(bestDist),
    snappedCoordinates: null,
    isCorridorMatched: false
  };
}
